    "// NAND Is Universal — NOT, AND and OR, Built From NAND Alone",
    "//",
    "// not_from_nand(a) = NAND(a, a); and_from_nand(a, b) = NAND(n, n) where",
    "// n = NAND(a, b); or_from_nand(a, b) = NAND(NAND(a, a), NAND(b, b)). Every",
